guidance.correct_example:
INVALID_RESULT: Result[Any] = Result.failure('Irrecoverable state')

def process(a_data: dict) -> Result[str]:
    result: Result[str] = INVALID_RESULT
    b_continue = True
    if not isinstance(a_data, dict):
        result = Result.failure('Expected dict')
        b_continue = False
    if b_continue:
        result = Result.success(a_data.get('name', ''))
    return result

guidance.incorrect_example:
def process(a_data: dict) -> Result[str]:
    result = None
    if not isinstance(a_data, dict):
        return Result.failure('Expected dict')
    return Result.success(a_data.get('name', ''))
